# -*- coding: utf-8 -*-
B=[
dict(a=1,z=1,star=3,
lit='「耶和華啊，我與你爭辯的時候，你總是公義的；然而有一件事，我還要與你理論：惡人的道路為何亨通？行詭詐的人為何都得安逸？」',
key=[('公義','H6662','tsaddiq','公義的'),('爭辯','H7378','arib','打官司、爭訟'),('判斷','H4941','mishpatim','判決、公道'),('為何','H4069','maddua','為什麼'),('惡人','H7563','resha\'im','惡人'),('亨通','H6743','tsalekhah','順利、成功'),('安逸','H7951','shalu','安逸、無憂')],
gram=['**{H7378}**（rib，爭訟）：這是一個**法庭用語**，意思是「向對方提出訴訟」。先知不是在發牢騷，而是正式向神提起訴訟，但是他一開始就承認：「你總是公義的（**{H6662}**）」。','**{H4069}**（maddua，為何）：這個疑問詞，在耶利米書出現得很頻繁（八章五節、十四章十九節），是一個**真誠的問**，不是挑戰。**{H6743}**（亨通）常被用在「耶和華使他事事順利」的好意上，這裡卻用在惡人身上，造成最大的張力。'],
exp=['這是一節**勇敢的禱告**：「耶和華啊，我與你爭辯的時候，你顯為義」。先知先把立場說清楚：我知道你是公義的。然後，他才說：但是我還有一個問題。**真誠的疑問，是從承認神是公義的開始。**','他的問題很直接：惡人的道路為何亨通？行詭詐的為何得安逸？這是詩篇七十三篇、哈巴谷書一章的同一個問題，是整本聖經裡最古老的痛：**好人受苦，壞人得意。**','這裡有一件事值得留意：先知把這個問題**直接帶到神面前**，沒有私下抱怨，也沒有放棄信仰。他用的是「爭辯」，是法庭的語言，他相信神有一個可以聽的耳朵。這給我們一個很大的鼓勵：**我們可以帶著最真實的疑問，來到神面前。**']),
dict(a=2,z=3,star=3,
lit='「你栽培了他們，他們也扎了根，長大，而且結果；他們的口與你相近，心卻與你遠離。耶和華啊，你曉得我，你看見我，你察驗我向你是怎樣的心。求你把他們像宰殺的羊一樣拉出來，把他們分別出來，等候殺戮的日子。」',
key=[('栽培','H5193','neta\'tam','栽種'),('扎根','H8327','shorashu','生根'),('結果','H6529','peri','果子'),('相近','H7138','qarov','靠近'),('遠離','H7350','rachoq','遙遠'),('肺腑','H3629','kilyotehem','腎；內心最深處'),('察驗','H974','uvachanta','試驗、查驗')],
gram=['**{H7138}**（qarov，靠近）與 **{H7350}**（rachoq，遙遠）：「口與你相近，心與你遠離」，是一組**反義**。口在嘴邊，心在遠處；外面近，裡面遠。','**{H3629}**（kilyotehem，腎）：直譯是「從他們的腎」，在希伯來人的思想裡，腎是人最深的情感與良心所在（參十一章二十節）。「遠離他們的腎」，意思是在他們最深處，並沒有神。'],
exp=['二節的控訴很細緻：你栽培了他們，他們扎了根，長大，也結果。這是一幅**繁榮的畫面**：神自己栽種，他們也確實茂盛。然後是最後一句：他們的口與你相近，心卻與你遠離。**一個人可以天天提到神的名，心卻不在那裡。**','三節轉過來，是先知對自己的陳述：「你曉得我，你看見我，你察驗我向你是怎樣的心」。你看，他拿**自己的心**與惡人的心做對比：他們是口近心遠，他是被神察驗過的。這不是自誇，而是他唯一可以倚靠的：**神知道我的心。**','接著先知說了一句很重的禱告：把他們拉出來，像將宰的羊。這是一個**詩篇式的呼求**（參詩篇七十三篇十七至十九節），先知把審判交給神。我們要小心讀：新約教導我們愛仇敵，也教導我們把審判交給神。**我們可以學習他的誠實，不必學習他的咒詛。**']),
dict(a=4,z=4,star=2,
lit='「這地悲哀，遍地的青草枯乾，要到幾時呢？因為居民的惡行，牲畜和飛鳥都滅絕了。他們曾說：他看不見我們的結局。」',
key=[('悲哀','H56','te\'evel','哀悼'),('青草','H6212','esev','草'),('枯乾','H3001','yivesh','枯乾'),('滅絕','H5595','safatah','被掃去'),('結局','H319','acharitenu','末後、結局'),('看見','H7200','yire\'eh','看見')],
gram=['**{H56}**（avel，哀悼）：「這地悲哀」是擬人的筆法，把大地當作一個在服喪的人。這與九章十節、十二章十一節呼應：**大地也為人的罪哀哭。**','**{H319}**（acharit，結局）：他們說：「他看不見我們的結局」。有的抄本作「神看不見我們的結局」，這裡有一個**對神的輕視**：我做的，神不知道。'],
exp=['這一節是一幅**生態的哀歌**：大地悲哀，青草枯乾，牲畜與飛鳥都滅絕了。人的罪，不只傷人，也傷了整個被造界。先知問：要到幾時呢？這是一個**所有受苦的人都會問的問題**：幾時才結束？','最後一句是惡人的自白：「他看不見我們的結局」。這是一個很深的謊言：**以為神看不見。**一個人若相信神看不見，他就會放膽行惡。這與先知前一節的禱告形成鮮明對比：先知相信神看見（「你曉得我，你看見我」），他們相信神看不見。']),
dict(a=5,z=5,star=3,
lit='「你若與步行的人同跑，尚且覺得疲累，怎能與馬賽跑呢？你在平安之地雖然安穩，在約旦河邊的叢林，又要怎麼辦呢？」',
key=[('步行的人','H7273','raglayim','徒步的人'),('跑','H7323','ratsta','跑'),('疲累','H3811','va-yal\'ukha','使你疲倦'),('賽跑','H8474','tetchareh','競爭、較量'),('馬','H5483','ha-susim','馬匹'),('安穩','H982','boteach','倚靠、安穩'),('叢林','H1347','ge\'on','驕傲、茂密的叢林')],
gram=['**{H8474}**（chara，較量）：這個字常指「與人較勁」，也有「發怒、激動」的意思。神的問題，是問先知：你連「小事」都撐不住，何況「大事」？','**{H1347}**（ge\'on，叢林；也作「驕傲」）：這個字在約旦河邊，指河邊茂密、野獸出沒的叢林。這是一個**雙關**：驕傲的叢林，也就是前面的路更艱險。**{H982}**（安穩）則是「倚靠」的意思：你在平安之地的倚靠，在叢林裡還站得住嗎？'],
exp=['神的第一個回答，讓人很意外。先知問的是：惡人為何亨通？神卻不回答這個問題，而是反問先知：**你若與步行的人同跑，尚且覺累，怎能與馬賽跑呢？**','這個回答，不是在責備，而是在**預備**。神的意思是：你現在覺得累，是因為你與人同跑；以後你要面對的，是與馬賽跑。你在平安之地都覺得不安穩，在約旦河邊的叢林，你要怎麼辦呢？這是一個很溫柔、也很嚴肅的提醒：**前面的路更艱險。**','請留意：神沒有說「你不該問」，也沒有說「你不要累」。祂只是告訴先知：你要預備，因為你要被造就。**這是神對一個真誠發問的僕人的回答：不是給解釋，是給預備。**']),
dict(a=6,z=6,star=3,
lit='「連你的弟兄和你父親的家，也都用詭詐待你；他們也在你後面大聲喊叫。他們雖然對你說好話，你也不要信他們。」',
key=[('弟兄','H251','achikha','你的弟兄'),('父','H1','avikha','你的父親'),('詭詐','H898','bagdu','背信、詭詐'),('喊叫','H7121','qar\'u','呼喊'),('滿聲','H4392','male','充滿；大聲'),('信','H539','ta\'amin','相信'),('好話','H2896','tovot','好事、善言')],
gram=['**{H898}**（bagad，背信）：這個字在這一章的第一節出現（「行詭詐的」），這裡又出現，並且用在**先知自己的親人身上**：與一節的「惡人」遙相呼應。','**{H539}**（aman，相信）：「你不要信他們」，這是一個很直接的提醒。這個字根，也是「阿們」的字根：不要在他們的好話上說「阿們」。'],
exp=['六節是這一段最**痛**的一節：連你的弟兄和你父親的家，也都用詭詐待你。這與十一章二十一節連在一起：先知被家鄉人要殺，現在連**自己的家人**也背叛他。','這給了先知一個重要的提醒：不要信他們的好話。這不是教他變得多疑，而是告訴他：**你要預備，有些關係會讓你失望。**這是神對一位被家人傷害的先知，最誠實的安慰。','這裡有一個很重要的提醒：神沒有說「你們要彼此和好」，因為在這個時刻，那是不可能的。祂只說：你要知道，這是真的。有時候，**承認痛苦是真的，比急著要人饒恕，更是一種愛。**']),
dict(a=7,z=9,star=3,
lit='「我離棄了我的殿，撇棄了我的產業；我把我心所愛的交在她仇敵的手中。我的產業對我如林中的獅子；她發聲攻擊我，所以我恨惡她。我的產業對我豈像斑點的鷙鳥嗎？鷙鳥豈在她四圍攻擊她嗎？你們要去聚集田野的百獸，帶來吞吃吧！」',
key=[('離棄','H5800','azavti','離棄、拋下'),('撇棄','H5203','natashti','丟棄、鬆手'),('所愛的','H3033','yedidut','所愛的'),('仇敵','H341','oyvehah','她的仇敵'),('獅子','H738','ka-aryeh','獅子'),('鷙鳥','H6641','tsavua','有斑點的'),('百獸','H2416','chayyat','走獸')],
gram=['**{H5800}**（azav，離棄）與 **{H5203}**（natash，撇棄）：兩個動詞連用，形成**很重的語氣**：我離開了我的殿，我鬆開了我的手。這是神的說話，是一位**被迫放手的父親**。','**{H3033}**（yedidut，所愛的）：這是十一章十五節的「我所親愛的」同字根。**一位把最愛的交出去的神，心裡的痛，比被交出去的人還大。**'],
exp=['七到九節是整章**最讓人震驚的一段**，因為這裡說話的，是神自己。祂說：我離棄了我的殿，撇棄了我的產業；我把我心所愛的，交在她仇敵的手中。你有沒有注意到這個語氣？這不是冷冰冰的審判，而是**一位心碎的父親**。','八節很特別：我的產業對我如林中的獅子，她向我發聲攻擊，所以我恨惡她。這個「恨惡」，在希伯來文，不是情緒上的恨，而是**一種關係的斷裂**：她既然與我為敵，我就把她交出去。可是前一節有「所愛的」，這裡有「恨惡」，兩個字放在一起，是一位**愛恨交織的神**。','九節以反問結束：我的產業豈如斑點的鷙鳥？鷙鳥豈在她四圍攻擊她呢？這是一個很難翻譯的句子，但意思大概是：我的百姓成了一隻怪鳥，其他的鳥都來攻擊牠；你們要把野獸都叫來吃吧。**這一段，是神哀悼自己的子民。**']),
dict(a=10,z=11,star=2,
lit='「許多牧人毀壞了我的葡萄園，踐踏了我的田地，使我心愛的田地變成荒涼的曠野。他們使它荒涼；它荒涼，向我哀號。全地都荒涼了，因為沒有人放在心上。」',
key=[('牧人','H7462','ro\'im','牧人；指領袖'),('毀壞','H7843','shichatu','毀壞'),('葡萄園','H3754','karmi','我的葡萄園'),('踐踏','H947','bossu','踐踏'),('心愛的','H2532','chemdati','我所喜愛的'),('荒涼','H8077','shemamah','荒涼'),('哀號','H56','avelah','哀悼')],
gram=['**{H7462}**（ro\'im，牧人）：「牧人」在耶利米書，常指君王、祭司與先知（二章八節、十章二十一節）。**十章二十一節說「牧人成為畜類」，這裡說「牧人毀壞葡萄園」。**','**{H8077}**（shemamah，荒涼）：這個字在這兩節出現了好幾次（含不同字形），像一個**回音**：荒涼，荒涼，荒涼。'],
exp=['十節的比喻，從獅子與鷙鳥，變成了**葡萄園**。神說：許多牧人毀壞了我的葡萄園。這是以賽亞書五章的同一個比喻。園丁是神，葡萄園是百姓，而**牧人（領袖）卻是毀壞它的人**。','「荒涼」這個字，在十到十一節出現了好幾次。荒涼，向我哀號。大地本身，成了一個哀哭的見證。這與四節的「這地悲哀」遙相呼應。','最後一句，是這一段**最令人心痛**的診斷：全地都荒涼了，因為**沒有人放在心上**。不是沒有人看見，而是沒有人在乎。冷漠，是一個民族最大的危機。']),
dict(a=12,z=13,star=2,
lit='「滅命的都來到曠野中一切光禿的高處；耶和華的刀從地這頭直到地那頭都在吞滅，凡有血氣的都不得平安。他們種的是麥子，收的卻是荊棘；他們勞苦，卻毫無益處。因耶和華的烈怒，你們必因自己的出產而羞愧。」',
key=[('光禿的高處','H8205','shefayim','光禿的山丘'),('滅命的','H7703','shodedim','毀滅者'),('刀','H2719','cherev','刀劍'),('血氣','H1320','basar','肉身、有血氣的'),('麥子','H2406','chittim','小麥'),('荊棘','H6975','qotsim','荊棘'),('烈怒','H2740','charon','烈怒')],
gram=['**{H2406}**（chittim，麥子）與 **{H6975}**（qotsim，荊棘）：種下麥子，收的是荊棘。這個畫面是**創世記三章十八節**的回聲：亞當犯罪之後，地要長出荊棘蒺藜。','**{H639}**（af，怒氣；本義是「鼻子」）：與 **{H2740}**（charon，烈怒）連用，形容神的怒氣像鼻孔噴氣一樣，是一個很具體的畫面。'],
exp=['十二節是一幅可怕的畫面：滅命的來到曠野一切光禿的高處；耶和華的刀從地這頭直到那頭。「凡有血氣的」，意思是**所有的人**，都不得平安。這是審判的普遍性。','十三節的比喻很簡單，也很深：種的是麥子，收的是荊棘。這是一種**倒反**：一般說人種什麼就收什麼（加六章七節），這裡卻是種了麥子，收到荊棘，因為整片土地都在審判之下，人的勞苦也跟著落空。','「因耶和華的烈怒，你們必因自己的出產而羞愧」。這是一個很重的結論：他們一生的勞苦，到最後只是羞愧。**一個沒有神的收成，終究是羞愧。**']),
dict(a=14,z=15,star=3,
lit='「耶和華這樣說：所有侵佔我賜給我百姓以色列作產業的壞鄰居，我要把他們從本地拔出來，也要把猶大家從他們中間拔出來。我拔出他們之後，我必回頭憐憫他們，使他們各歸本業，各回本地。」',
key=[('鄰居','H7934','shekhenai','鄰居'),('侵佔','H5060','ha-noge\'im','觸摸、侵犯'),('承受','H5157','hinchaltiy','使承受產業'),('拔出','H5428','nitsham','拔起'),('地土','H127','adamatam','土地'),('憐憫','H7355','vericham-tim','憐憫、有慈心')],
gram=['**{H5428}**（natash，拔出）：這是耶利米書一章十節那六個動詞的第一個：拔出、拆毀、毀滅、傾覆，建立、栽植。**這裡拔出的對象，是「壞鄰居」，也是「猶大家」**，所以審判對所有人都是公平的。','**{H7355}**（racham，憐憫）：這個字與「子宮」（**rechem**）同字根，是母親對孩子的**那種肚腸的憐憫**。神說：拔出之後，我必轉過來憐憫他們。**拔出之後還有憐憫。**'],
exp=['十四節是一個轉折：神突然轉向了**以色列的鄰國**。祂說：那些侵佔我百姓產業的壞鄰居，我要把他們拔出本地；同時，我也要把猶大家從他們中間拔出來。這很有意思：**神的審判是雙向的**。對外邦人，對自己的子民，同樣公平。','十五節是整章的**高峰**：我拔出他們以後，我必轉過來憐憫他們。「憐憫」這個字，與「子宮」同字根：是母親對孩子**最深的肚腸**。你看，神的審判，從來不是最後一句。**拔出之後，是憐憫；憐憫之後，是歸回。**','這個應許，與一章十節的六個動詞完全對應：**先拔，後栽**。神拔，是為了栽；神拆，是為了建。這給了我們一個很重要的提醒：**神的管教與審判，是為了更新。**']),
dict(a=16,z=17,star=3,
lit='「他們若殷勤學習我百姓的道，指著我的名起誓說：我指著永生的耶和華起誓，正如他們從前教我的百姓指著巴力起誓，他們就必建立在我的百姓中間。他們若是不聽，我必拔出那國，拔出而且毀滅。這是耶和華的宣告。」',
key=[('道','H1870','darkhey','道路、行事的方式'),('名','H8034','bishmi','我的名'),('永生','H2416','chay','活著的'),('巴力','H1168','ba\'al','巴力'),('建立','H1129','venivnu','被建造'),('聽','H8085','yishme\'u','聽從'),('列國','H1471','ha-goy','那國')],
gram=['**{H1129}**（banah，建立）：這是一章十節的第二組動詞：「建立、栽植」。**外邦人若學習神的道，就能被「建立」在神百姓中間。**','**{H2416}**（chai，活著的）：「指著永生的耶和華起誓」，是以色列人最常用的誓言。外邦人若學會這句話，就**成為神百姓的一部分**。'],
exp=['十六節是全章最令人驚喜的一節：**外邦人也有機會。**他們若殷勤學習神百姓的道，指著永生的耶和華起誓，就必建立在神的百姓中間。這不是一個小小的應許，而是整本聖經最大的一條線：**神的家，向萬國敞開。**','請看這個比喻：他們從前教以色列人指著巴力起誓；現在，他們若學習指著耶和華起誓，就有地位。**曾經帶人走錯路的人，也可以帶人走對路。**這是一個很深的恩典：不管你過去教過別人什麼，你仍然可以重新學習。','十七節是**選擇的另一面**：若是不聽，我必拔出那國，拔出而且毀滅。這是一個清楚的二選一：聽，被建立；不聽，被拔出。**神給了每一個國家、每一個人，同一個選擇。**這給了這一章一個溫柔而嚴肅的結尾：惡人的亨通，不是終點；神的審判與恩典，才是終點。']),
]
